<?php
declare(strict_types=1);
/* Preview-domain validation. Live accounts/files use the separately protected backend. */
function ns_engineering_fields():array {return ['owner_name','owner_phone','mailing_address','dr_environmental_id','subdivision','lot_dimensions','water_supplier','benchmark','datum','project_kind','system_type','treatment','disposal','receipt','permit_number','approval_date','construction_started','notes','stub_elev','tank_elev','dbox_elev','trench_elev','tank_gal','dose_gal','daily_flow','field_lines','line_length','trench_width','trench_depth','trench_spacing','absorption_area','primary_bedrock','primary_bswt','primary_mswt','primary_lswt','primary_adj_mswt','primary_adj_lswt','primary_hc_depth','primary_loading','secondary_bedrock','secondary_bswt','secondary_mswt','secondary_lswt','secondary_adj_mswt','secondary_adj_lswt','secondary_hc_depth','secondary_loading'];}
function ns_engineering_record(array $d):array {
 $out=[];$text=['owner_name','owner_phone','mailing_address','dr_environmental_id','subdivision','lot_dimensions','water_supplier','benchmark','datum','project_kind','system_type','treatment','disposal','receipt','permit_number','approval_date','notes'];
 foreach(ns_engineering_fields() as $key){$v=$d[$key]??'';if($key==='construction_started'){$out[$key]=in_array($v,[true,1,'1','on'],true);continue;}if(in_array($key,$text,true)){$out[$key]=substr(trim((string)$v),0,$key==='notes'?3000:200);continue;}if($v===''||$v===null){$out[$key]=null;continue;}if(!is_numeric($v)||!is_finite((float)$v)||abs((float)$v)>100000||((float)$v<0&&!str_ends_with($key,'_elev')))throw new DomainException('Use a valid measurement for '.str_replace('_',' ',$key).'.');$out[$key]=(float)$v;}
 if($out['approval_date']!==''){if(!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$out['approval_date'],$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))throw new DomainException('Enter a valid health-authority approval date.');}
 foreach(['system_type'=>['','Standard','Pumped','Drip','ATU','Other'],'treatment'=>['','STD','ISF','PMF','OTH','ATU','RSF','RGF','HLD'],'disposal'=>['','STD','SUR','CPF','OTH','LPD','HLD','SRL','DRP']] as $k=>$allowed)if(!in_array($out[$k],$allowed,true))throw new DomainException('Choose a listed '. $k.'.');
 return $out;
}
function ns_coordinates(mixed $p):bool{return is_array($p)&&count($p)===2&&is_numeric($p[0])&&is_numeric($p[1])&&is_finite((float)$p[0])&&is_finite((float)$p[1])&&abs((float)$p[0])<=180&&abs((float)$p[1])<=90;}
function ns_features(array $items,string $role,array $previous=[]):array {
 if(count($items)>100)throw new DomainException('Keep this preview to 100 site features per job.');$out=[];$ids=[];
 foreach($items as $f){if(!is_array($f)||!in_array($f['kind']??'',['Soil Pit','Water Well','Structure/Stub-out','Lateral Corner','Hazard/Rock','Benchmark','Tank','D-box','Primary Area','Reserve Area','Lateral Line','Measurement'],true))throw new DomainException('Choose a valid site feature type.');$id=substr((string)($f['id']??''),0,80);if(!$id||isset($ids[$id]))throw new DomainException('Site feature identifiers must be unique.');$ids[$id]=true;$g=$f['geometry']??[];$type=$g['type']??'';$c=$g['coordinates']??null;
 if($type==='Point'){$valid=ns_coordinates($c);}elseif($type==='LineString'){$valid=is_array($c)&&count($c)>=2&&count($c)<=100;foreach($c??[] as $p)$valid=$valid&&ns_coordinates($p);}elseif($type==='Polygon'){$ring=$c[0]??[];$valid=is_array($ring)&&count($ring)>=4&&count($ring)<=101&&reset($ring)===end($ring);foreach($ring as $p)$valid=$valid&&ns_coordinates($p);}else{$valid=false;}if(!$valid)throw new DomainException('Use valid coordinates and a closed outline for site areas.');if(in_array($f['kind'],['Primary Area','Reserve Area'],true)&&$type!=='Polygon')throw new DomainException('Use a polygon for an area outline.');if(in_array($f['kind'],['Lateral Line','Measurement'],true)&&$type!=='LineString')throw new DomainException('Use a line geometry for this feature.');if(!in_array($f['kind'],['Primary Area','Reserve Area','Lateral Line','Measurement'],true)&&$type!=='Point')throw new DomainException('Use a point for this site feature.');
 $verified=$role==='engineer'&&!empty($f['verified']);if($role!=='engineer')foreach($previous as $old)if(($old['id']??'')===$id&&($old['geometry']??[])===$g&&($old['kind']??'')===$f['kind']&&($old['label']??'')===($f['label']??'')&&($old['note']??'')===($f['note']??'')&&($old['observations']??[])===($f['observations']??[])&&($old['source']??'')===($f['source']??'')&&($old['accuracy_ft']??null)===($f['accuracy_ft']??null))$verified=!empty($old['verified']);
 $accuracy=$f['accuracy_ft']??null;if($accuracy!==null&&(!is_numeric($accuracy)||(float)$accuracy<0||(float)$accuracy>100000))throw new DomainException('Accuracy must be a non-negative number of feet.');
 $obs=[];foreach(['depth','bedrock','bswt','mswt','lswt','loading'] as $key){$v=$f['observations'][$key]??null;if($v!==null&&$v!==''&&(!is_numeric($v)||!is_finite((float)$v)||(float)$v<0||(float)$v>100000))throw new DomainException('Use a valid pit measurement.');$obs[$key]=$v===null||$v===''?null:(float)$v;}$obs['notes']=substr(trim((string)($f['observations']['notes']??'')),0,1500);
 $out[]=['observations'=>$obs,'id'=>$id,'kind'=>$f['kind'],'label'=>substr(trim((string)($f['label']??$f['kind'])),0,100),'note'=>substr(trim((string)($f['note']??'')),0,1000),'geometry'=>$g,'source'=>substr((string)($f['source']??'Map placement'),0,100),'accuracy_ft'=>$accuracy===null?null:(float)$accuracy,'verified'=>$verified,'recorded'=>time()];
 }return $out;
}
function ns_queue_update(array &$job,string $kind,string $actor,array $d=[]):void {
 $job['notifications']??=[];if(count($job['notifications'])>=100)array_shift($job['notifications']);$eta=$d['eta_minutes']??null;if($eta!==null&&$eta!==''&&(!is_numeric($eta)||(int)$eta<0||(int)$eta>1440))throw new DomainException('Enter an ETA between 0 and 1440 minutes.');
 $job['notifications'][]=['id'=>'UPDATE-'.bin2hex(random_bytes(5)),'kind'=>$kind,'actor'=>$actor,'created'=>time(),'eta_minutes'=>($eta===null||$eta==='')?null:(int)$eta,'window_minutes'=>15,'delivery'=>'Preview only — not sent','invoice_url'=>$job['billing']['invoice_url']??'','note'=>substr(trim((string)($d['note']??'')),0,1000)];
}
function ns_extension_action(array &$job,string $action,string $role,array $d,string &$label):bool {
 if($action==='site_features'){field_role($role,['operator','engineer']);$job['site_features']=ns_features(is_array($d['features']??null)?$d['features']:[],$role,$job['site_features']??[]);$label='Site features and measurements saved';return true;}
 if($action==='engineering_record'){field_role($role,['engineer']);$record=ns_engineering_record(is_array($d['record']??null)?$d['record']:[]);$job['engineering_revisions']??=[];if(count($job['engineering_revisions'])>=30)throw new DomainException('The preview allows 30 engineering record versions.');$record['recorded']=time();$record['author']='Tylor';$job['engineering_record']=$record;$job['engineering_revisions'][]=$record;$label='Engineering field record saved';return true;}
 if($action==='customer_update'){field_role($role,['operator','engineer']);$kind=(string)($d['kind']??'');if(!in_array($kind,['On the Way','Delayed','Arrived','Eval Complete','Invoice Ready'],true))throw new DomainException('Choose a listed customer update.');ns_queue_update($job,$kind,$role,$d);$label='Customer update prepared: '.$kind;return true;}
 if($action==='photo_recorded'){$label='Pit photo recorded';ns_queue_update($job,'Pit Photo Uploaded',$role,$d);return true;}
 if($action==='billing'){field_role($role,['operator','engineer']);$url=trim((string)($d['invoice_url']??''));if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||strtolower((string)parse_url($url,PHP_URL_SCHEME))!=='https'))throw new DomainException('Use an HTTPS invoice link or leave it blank.');$method=(string)($d['method']??'Unpaid');if(!in_array($method,['Unpaid','Cash','Check','Online'],true))throw new DomainException('Choose a listed payment method.');$job['billing']=['invoice_url'=>substr($url,0,1000),'method'=>$method,'paid'=>$method!=='Unpaid','recorded'=>time(),'actor'=>$role,'reference'=>field_text($d,'reference',200)];$label=$method==='Unpaid'?'Invoice details saved':'Payment recorded: '.$method;return true;}
 return false;
}
function ns_seed_site(array $j):array {
 if(!is_numeric($j['lat']??null)||!is_numeric($j['lng']??null))return [];$x=(float)$j['lng'];$y=(float)$j['lat'];$points=[['Soil Pit','P-01',0,0],['Soil Pit','P-02',.0003,-.00025],['Water Well','W-01',-.00065,.0002],['Structure/Stub-out','S-01',.0001,.00045],['Benchmark','BM-01',-.0002,.0005]];$out=[];
 foreach($points as $i=>[$kind,$label,$dx,$dy])$out[]=['id'=>'EXAMPLE-'.($i+1),'kind'=>$kind,'label'=>$label,'note'=>'Mock-up site feature for the working preview.','geometry'=>['type'=>'Point','coordinates'=>[$x+$dx,$y+$dy]],'source'=>'Mock-up layout','accuracy_ft'=>null,'verified'=>false,'recorded'=>time()];
 $out[]=['id'=>'EXAMPLE-AREA','kind'=>'Primary Area','label'=>'Primary dispersal area','note'=>'Concept outline for the mock-up job.','geometry'=>['type'=>'Polygon','coordinates'=>[[[$x+.0002,$y-.0001],[$x+.00065,$y-.0001],[$x+.00065,$y-.0005],[$x+.0002,$y-.0005],[$x+.0002,$y-.0001]]]],'source'=>'Mock-up layout','accuracy_ft'=>null,'verified'=>false,'recorded'=>time()];return $out;
}
